            ["hinge", "thickness", [101.5, 10, 5], [0, 0, -1], 0.6],
            ["rib", "material", [[20, 1.2, 3.5], [80, 2.3, 5.0]], 1],
            ["latch_tower", "material", [[3, 6, 3.5], [7, 14, 5.0]], 1],
